  const offerExpired = activeEarlierSlotOffer ? Date.parse(activeEarlierSlotOffer.offer!.expiresAt) <= offerNow : false;
  const offerMinutesLeft = activeEarlierSlotOffer ? Math.max(0, Math.ceil((Date.parse(activeEarlierSlotOffer.offer!.expiresAt) - offerNow) / (60 * 1000))) : 0;
